{"command":"node -e "
const path = require('path');
const engine = require('./operations/science/research/predicated-zork/engine.js');
const world = engine.loadWorld(path.join(__dirname, 'operations/science/research/predicated-zork/zork-world-generated.json'));
const rules = engine.loadRules(
  'operations/science/research/predicated-zork/zork-verbs.json',
  'operations/science/research/predicated-zork/zork-object-rules.json',
  'operations/science/research/predicated-zork/zork-combat-rules.json',
  'operations/science/research/predicated-zork/zork-darkness-rules.json',
  'operations/science/research/predicated-zork/zork-scoring-rules.json',
  'operations/science/research/predicated-zork/zork-maze-rules.json',
  'operations/science/research/predicated-zork/zork-thief-rules.json',
  'operations/science/research/predicated-zork/zork-puzzle-rules.json'
);

world.entities.player = { id: 'player', type: 'actor', fiber: [['location', 'west-of-house', 't'], ['alive', true, 't'], ['score', 0, 't']] };
world.entities.mailbox.fiber.push(['open', true, 'f']);
world.entities['kitchen-window'].fiber.push(['open', true, 'f']);
world.entities['trophy-case'].fiber.push(['open', true, 'f']);
world.entities.rug.fiber.push(['moved', true, 'f']);
world.entities['trap-door'].fiber.push(['open', true, 'f']);
world.entities.troll.fiber.push(['alive', true, 't']);

const cmds = [
  'open mailbox','drop leaflet','go south','go east','open window','go west','go west',
  'take lamp','move rug','open trap door','turn on lamp','go down','take sword',
  'go north',  // should be troll room
  'kill troll with sword',
  'go east',  // should work after troll dies
];

for (const cmd of cmds) {
  // Mini parser
  const parts = cmd.split(/\\s+/);
  const dirMap = {north:'north',south:'south',east:'east',west:'west',up:'up',down:'down'};
  let result;
  if (parts[0] === 'go' && dirMap[parts[1]]) {
    result = engine.act(world, rules, { player: 'player', verb: 'go', direction: dirMap[parts[1]] });
  } else if (parts[0] === 'kill' || parts[0] === 'attack') {
    const withIdx = parts.indexOf('with');
    const dObj = withIdx > 1 ? parts.slice(1, withIdx).join(' ') : parts.slice(1).join(' ');
    const iObj = withIdx >= 0 ? parts.slice(withIdx+1).join(' ') : null;
    result = engine.act(world, rules, { player: 'player', verb: 'attack', directObject: dObj, indirectObject: iObj });
  } else {
    const verb = parts[0];
    const rest = parts.slice(1).filter(w=>!['the','a','in','on','with'].includes(w));
    result = engine.act(world, rules, { player: 'player', verb: verb, directObject: rest[0] || null });
  }
  const loc = (world.entities.player.fiber.find(f=>f[0]==='location'&&f[2]==='t')||[])[1];
  console.log(cmd + ' → ' + (result.text||'').slice(0,50) + ' [rule:' + (result.rule||'none') + '] [loc:' + loc + ']');
}
"","description":"Trace full flow with combat"}

