/**
 * Phase 1: Δ (respond) — merge via ∨_k (knowledge-order join).
 *
 * Where entity and message AGREE: value stays (t ∨_k t = t).
 * Where entity and message DISAGREE: value becomes ⊤ (f ∨_k t = ⊤).
 * Where message is SILENT: entity's value stays (t ∨_k ⊥ = t).
 * Where entity is SILENT: message's value is accepted (⊥ ∨_k t = t).
 */
function mergeFibers(entityFiber, messageFiber) {
  const merged = new Map();
  const allKeys = new Set([...entityFiber.keys(), ...messageFiber.keys()]);
  for (const key of allKeys) {
    const eVal = entityFiber.get(key) || BOT;
    const mVal = messageFiber.get(key) || BOT;
    merged.set(key, kJoin(eVal, mVal));
  }
  return merged;
}

/**
 * Phase 2: σ (settle) — resolve ⊤ via ⊙ (extend) with message evidence.
 *
 * ⊤ ⊙ t = t  (affirmation resolves contest)
 * ⊤ ⊙ f = f  (denial resolves contest)
 * ⊤ ⊙ ⊥ = ⊥  (no evidence → drops to unknown)
 * ⊤ ⊙ ⊤ = ⊤  (mutual contest → stays contested)
 *
 * Non-⊤ values pass through unchanged — already settled.
 */
function settleFibers(mergedFiber, messageFiber) {
  const settled = new Map();
  for (const [key, val] of mergedFiber) {
    if (equals(val, TOP)) {
      const evidence = messageFiber.get(key) || BOT;
      settled.set(key, extend(TOP, evidence));
    } else {
      settled.set(key, val);
    }
  }
  return settled;
}

