 * respond(entityId, message, db) → responseMessage
 *
 * The primitive. Computes σ∘Δ: merge via ∨_k, settle via ⊙.
 *
 * @param {string} entityId - id of any entity in the graph
 * @param {object} message - {channel, payload, sender, time}
 * @param {object} db - loaded query index from datastore.load()
 * @returns {object} response message with { payload, contested, delta }
 */
function respond(entityId, message, db) {
  // 1. Build entity fiber
  const entityFiber = buildEntityFiber(db, entityId);
  if (entityFiber === null) {
    return { error: "entity-not-found", entityId };
  }

  // Edge: empty payload → return entity's own fiber (pure query)
  if (!message.payload || Object.keys(message.payload).length === 0) {
    return {
      channel: message.channel || "default",
      payload: fiberToPayload(entityFiber),
      sender: entityId,
      time: Date.now(),
    };
  }

  // 2. Build message fiber
  const msgFiber = buildMessageFiber(message.payload);

  // 3. Δ: merge entity ∨_k message (introduces ⊤ where they disagree)
  const merged = mergeFibers(entityFiber, msgFiber);

  // 4. Track what became contested
  const contested = [];
  for (const [key, val] of merged) {
    if (equals(val, TOP)) contested.push(key);
  }

  // 5. σ: settle ⊤ values using message as evidence
  const settled = settleFibers(merged, msgFiber);

  // 6. Compute delta (what changed from entity's original fiber)
  const delta = {};
  for (const [key, val] of settled) {
    const orig = entityFiber.get(key) || BOT;
    if (!equals(orig, val)) {
      delta[key] = { from: name(orig), to: name(val) };
    }
  }

