/**
 * play.js — Play predicated Zork.
 *
 * The thinnest possible shell: read text → respond() → print text.
 * All game logic is in the algebra (∨_k/⊙ on entity fibers).
 *
 * Run: node operations/science/research/predicated-zork/play.js
 */
"use strict";

const readline = require("readline");
const path = require("path");
const alg = require("./algebraic-engine.js");

// ── Load world ────────────────────────────────────────────────────

const world = alg.loadWorld(path.join(__dirname, "zork-world-generated.json"));

// Player entity
const player = {
  id: "player",
  fiber: new Map([["location:west-of-house", alg.T], ["alive:true", alg.T]]),
  meta: { type: "actor", descriptions: {}, exits: {}, synonyms: [], adjectives: [] },
  responses: {},
};
world.player = player;

// Initialize mutable state
function init(id, prop, val) {
  const e = world[id];
  if (e && !e.fiber.has(prop)) e.fiber.set(prop, val);
}
init("mailbox", "state:open", alg.F);
init("mailbox", "state:closed", alg.T);
init("kitchen-window", "state:open", alg.F);
init("kitchen-window", "state:closed", alg.T);

for (const [id, ent] of Object.entries(world)) {
  if (ent.meta?.type !== "object") continue;
  for (const [key, val] of ent.fiber) {
    if (key.startsWith("location:") && alg.equals(val, alg.T)) {
      ent.fiber.set("state:here", alg.T);
      ent.fiber.set("state:held", alg.F);
      break;
    }
  }
}

// ── Synonym resolution via fiber lookup ───────────────────────────

function getPlayerRoom() {
  for (const [key, val] of player.fiber) {
    if (key.startsWith("location:") && alg.equals(val, alg.T)) return key.split(":")[1];
  }
  return null;
}

function resolveNoun(word) {
  if (!word) return null;
  const term = word.toLowerCase();
  if (world[term]) return term;
  if (world[term.replace(/ /g, "-")]) return term.replace(/ /g, "-");

  const roomId = getPlayerRoom();
  const room = world[roomId];
  const globals = room ? [...room.fiber].filter(([k]) => k.startsWith("global-visible:")).map(([k]) => k.split(":")[1]) : [];

  let best = null, bestScore = -1;
  for (const [id, ent] of Object.entries(world)) {
    if (ent.meta?.type !== "object") continue;
    const syns = ent.meta.synonyms.map(s => s.toLowerCase());
    if (!syns.includes(term) && id !== term) continue;

    let score = 1;
    const loc = [...ent.fiber].find(([k, v]) => k.startsWith("location:") && alg.equals(v, alg.T));
    const locId = loc ? loc[0].split(":")[1] : null;
    if (locId === "player" || (ent.fiber.has("state:held") && alg.equals(ent.fiber.get("state:held"), alg.T))) score = 10;
    else if (locId === roomId) score = 8;
    else if (globals.includes(id)) score = 5;
    if (id.includes("broken") || id.includes("burned")) score -= 5;

    if (score > bestScore) { best = id; bestScore = score; }
  }
  return best;
}

// ── Parse ─────────────────────────────────────────────────────────

const DIRS = {
  n: "north", s: "south", e: "east", w: "west", u: "up", d: "down",
  north: "north", south: "south", east: "east", west: "west",
  up: "up", down: "down", ne: "ne", nw: "nw", se: "se", sw: "sw",
  in: "in", out: "out", enter: "in", exit: "out",
};

const VERBS = {
  l: "look", look: "look", x: "examine", examine: "examine",
  read: "read", take: "take", get: "take", drop: "drop",
  open: "open", close: "close", shut: "close",
  i: "inventory", inventory: "inventory",
  kill: "attack", attack: "attack", fight: "attack",
  move: "move", push: "move", pull: "move",
  q: "quit", quit: "quit",
};

function parse(line) {
  const raw = line.trim().toLowerCase();
  if (!raw) return null;
  if (raw === "q" || raw === "quit") return { verb: "quit" };
  if (DIRS[raw]) return { verb: "go", direction: DIRS[raw] };

  // "go north", "go east"
  if (raw.startsWith("go ")) {
    const d = DIRS[raw.slice(3).trim()];
    if (d) return { verb: "go", direction: d };
  }

  // "turn on X", "turn off X"
  if (raw.startsWith("turn on ")) return { verb: "turn-on", target: resolveNoun(raw.slice(8).trim()) };
  if (raw.startsWith("turn off ")) return { verb: "turn-off", target: resolveNoun(raw.slice(9).trim()) };
  if (raw.startsWith("look in ")) return { verb: "look-inside", target: resolveNoun(raw.slice(8).trim()) };

  const words = raw.split(/\s+/);
  const verb = VERBS[words[0]];
  if (!verb) {
    if (DIRS[words[0]]) return { verb: "go", direction: DIRS[words[0]] };
    return null;
  }
  if (verb === "look" && words.length === 1) return { verb: "look" };
  if (verb === "inventory") return { verb: "inventory" };

  // Split on "with" fo...[truncated]

